const setEventFlags = `-- name: SetEventFlags :one
WITH prev AS (
    SELECT x.id, x.remove_branding, x.template_id, x.template_version, x.overrides FROM events x
    WHERE x.id = $5 AND x.deleted_at IS NULL
    FOR NO KEY UPDATE
)
UPDATE events e
SET remove_branding = coalesce($1, e.remove_branding),
    template_id = coalesce($2, e.template_id),
    template_version = coalesce($3, e.template_version),
    overrides = coalesce($4, e.overrides),
    version = CASE WHEN $2::uuid IS NULL THEN e.version ELSE e.version + 1 END,
    updated_at = now()
FROM prev
WHERE e.id = prev.id
RETURNING e.id,
          prev.remove_branding AS old_remove_branding, prev.template_id AS old_template_id,
          prev.template_version AS old_template_version, prev.overrides AS old_overrides,
          e.remove_branding, e.template_id, e.template_version, e.overrides, e.version
`

