// No row: missing, deleted, already taken down, or a slug-less draft (never public).
func (q *Queries) TakeDownEvent(ctx context.Context, eventID uuid.UUID) (TakeDownEventRow, error) {
	row := q.db.QueryRow(ctx, takeDownEvent, eventID)
	var i TakeDownEventRow
	err := row.Scan(
		&i.ID,
		&i.OwnerID,
		&i.OldStatus,
		&i.NewStatus,
	)
	return i, err
}

const takeDownEventsByOwner = `-- name: TakeDownEventsByOwner :many
UPDATE events
SET status = 'taken_down', updated_at = now()
WHERE owner_id = $1::uuid
  AND deleted_at IS NULL
  AND status <> 'taken_down'
  AND slug IS NOT NULL
RETURNING id
`

// Ban. Drafts without a slug were never public and can't be taken down (events CHECK), so they are skipped.
func (q *Queries) TakeDownEventsByOwner(ctx context.Context, ownerID uuid.UUID) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, takeDownEventsByOwner, ownerID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

